/**
 * @file WebAuthn / passkeys: registration, login second factor, step-up, listing and revocation.
 * @module platform/auth
 *
 * Built on @simplewebauthn/server 14 (maintained, widely reviewed). Security properties:
 *  - Origin + RP ID binding (expectedOrigin = WEB_ORIGIN, expectedRPID = RP id): phishing sites
 *    cannot obtain a valid assertion.
 *  - User verification REQUIRED (PIN/biometric on the authenticator).
 *  - Challenges are 32 random bytes generated by the library, stored on the SESSION row with a
 *    purpose and 5-minute expiry, and cleared on first use (success or failure): no replay.
 *  - Registration requires a recent step-up (or is the admin's mandatory first passkey, which
 *    itself requires a fresh TOTP step-up) so a stolen session cannot silently add a key.
 *  - Only public keys are stored; sign counters are checked by the library and updated.
 *  - Credentials are scoped to the user (allowCredentials) and to the tenant (composite FK).
 */
import { randomUUID } from 'node:crypto';
import {
  generateAuthenticationOptions,
  generateRegistrationOptions,
  verifyAuthenticationResponse,
  verifyRegistrationResponse,
} from '@simplewebauthn/server';
import { sql } from 'drizzle-orm';
import type { z } from 'zod';
import type { WebAuthnAuthenticationResponse, WebAuthnRegistrationResponse } from '@autolemon/contracts';
import { type AppConfig, rpIdOf } from '../../config/env.js';
import { Conflict, NotFound, Unauthenticated } from '../../common/errors.js';
import type { Database } from '../../db/database.js';
import { asDate, row, rows } from '../../db/database.js';
import type { AuditService } from '../audit/audit.service.js';
import { type Actor, requireStepUp } from '../authz/actor.js';
import type { AuthService, ClientInfo, IssuedSession, SessionRow } from './auth.service.js';
import type { ThrottleService } from './throttle.service.js';

type Purpose = 'REGISTER' | 'AUTHENTICATE' | 'STEP_UP';

interface CredentialRow {
  id: string;
  user_id: string;
  credential_id: string;
  public_key: Buffer;
  sign_count: string;
  transports: string[];
  name: string;
}

const CHALLENGE_MINUTES = 5;

/** Passkey use cases. */
export class PasskeyService {
  constructor(
    private readonly database: Database,
    private readonly cfg: AppConfig,
    private readonly audit: AuditService,
    private readonly auth: AuthService,
    private readonly throttle: ThrottleService,
  ) {}

  private get rpId(): string {
    return rpIdOf(this.cfg);
  }

  // ------------------------------------------------------------------ registration

  /**
   * Creates registration options for the logged-in user. Requires a step-up within the
   * configured window (account.mfa.change).
   */
  async registrationOptions(actor: Actor) {
    requireStepUp(actor, 'account.mfa.change', this.cfg.STEP_UP_MINUTES);
    const user = await this.auth.userById(actor.userId);
    if (!user) throw new Unauthenticated();
    const existing = await this.credentials(actor.userId);
    const options = await generateRegistrationOptions({
      rpName: 'AutoLemon ERP',
      rpID: this.rpId,
      userName: user.email,
      userDisplayName: user.display_name,
      // Opaque user handle (no PII): the internal user UUID bytes.
      userID: new Uint8Array(Buffer.from(user.id.replace(/-/g, ''), 'hex')),
      attestationType: 'none',
      excludeCredentials: existing.map((c) => ({ id: c.credential_id, transports: c.transports })),
      authenticatorSelection: { residentKey: 'preferred', userVerification: 'required' },
      timeout: CHALLENGE_MINUTES * 60_000,
    });
    await this.storeChallenge(actor.sessionId, options.challenge, 'REGISTER');
    return options;
  }

  /** Verifies the registration response and stores the credential (audited, alert-worthy). */
  async register(actor: Actor, response: z.infer<typeof WebAuthnRegistrationResponse>, name: string) {
    requireStepUp(actor, 'account.mfa.change', this.cfg.STEP_UP_MINUTES);
    const challenge = await this.takeChallenge(actor.sessionId, 'REGISTER');
    let verification;
    try {
      verification = await verifyRegistrationResponse({
        response: response as never,
        expectedChallenge: challenge,
        expectedOrigin: this.cfg.WEB_ORIGIN,
        expectedRPID: this.rpId,
        requireUserVerification: true,
      });
    } catch {
      verification = { verified: false as const };
    }
    if (!verification.verified) {
      await this.audit.record({
        companyId: actor.companyId,
        actorUserId: actor.userId,
        action: 'auth.passkey.register',
        outcome: 'FAILURE',
        requestId: actor.requestId,
        clientIp: actor.clientIp,
      });
      throw new Conflict('Não foi possível validar a chave de acesso', 'PASSKEY_INVALID');
    }
    const info = verification.registrationInfo;
    const id = randomUUID();
    await this.database.systemTx(async (tx) => {
      await tx.execute(sql`INSERT INTO webauthn_credentials (id, user_id, company_id, credential_id, public_key, sign_count, transports,
            device_type, backed_up, aaguid, name)
          VALUES (${id}, ${actor.userId}, ${actor.companyId}, ${info.credential.id}, ${Buffer.from(info.credential.publicKey)},
            ${info.credential.counter},
            ARRAY(SELECT jsonb_array_elements_text(${JSON.stringify((info.credential.transports ?? []).filter((x) => /^[a-z-]{1,20}$/.test(x)))}::jsonb)), ${info.credentialDeviceType}, ${info.credentialBackedUp},
            ${info.aaguid}, ${name})`);
      await this.audit.recordInTx(tx, {
        companyId: actor.companyId,
        actorUserId: actor.userId,
        action: 'auth.passkey.register',
        resourceType: 'passkey',
        resourceId: id,
        outcome: 'SUCCESS',
        requestId: actor.requestId,
        clientIp: actor.clientIp,
        // A new authenticator on an account is an alerting signal.
        details: { alert: true, deviceType: info.credentialDeviceType },
      });
    });
    return { id, name };
  }

  /** Lists the caller's passkeys (no key material). */
  async list(actor: Actor) {
    return this.database.systemTx((tx) =>
      rows(
        tx,
        sql`SELECT id, name, device_type AS "deviceType", backed_up AS "backedUp", created_at AS "createdAt", last_used_at AS "lastUsedAt"
            FROM webauthn_credentials WHERE user_id = ${actor.userId} AND revoked_at IS NULL ORDER BY created_at`,
      ),
    );
  }

  /**
   * Revokes one of the caller's passkeys (step-up). Under the admin passkey policy the last
   * passkey cannot be removed (it would silently downgrade the account to TOTP).
   */
  async revoke(actor: Actor, passkeyId: string) {
    requireStepUp(actor, 'account.mfa.change', this.cfg.STEP_UP_MINUTES);
    const user = await this.auth.userById(actor.userId);
    if (!user) throw new Unauthenticated();
    const count = await this.auth.activePasskeyCount(actor.userId);
    if ((await this.auth.passkeyPolicyApplies(user)) && count <= 1) {
      throw new Conflict('A política exige pelo menos uma chave de acesso; registe outra antes de remover esta', 'LAST_PASSKEY');
    }
    await this.database.systemTx(async (tx) => {
      const r = await row<{ id: string }>(
        tx,
        sql`UPDATE webauthn_credentials SET revoked_at = now() WHERE id = ${passkeyId} AND user_id = ${actor.userId} AND revoked_at IS NULL RETURNING id`,
      );
      if (!r) throw new NotFound('Chave de acesso', 'passkey_scope');
      await this.audit.recordInTx(tx, {
        companyId: actor.companyId,
        actorUserId: actor.userId,
        action: 'auth.passkey.revoke',
        resourceType: 'passkey',
        resourceId: passkeyId,
        outcome: 'SUCCESS',
        requestId: actor.requestId,
        clientIp: actor.clientIp,
        details: { alert: true },
      });
    });
    return { id: passkeyId, revoked: true };
  }

  // ------------------------------------------------------------------ login & step-up

  /** Authentication options for a MFA_PENDING session (login second factor). */
  async loginOptions(session: SessionRow) {
    const creds = await this.credentials(session.user_id);
    if (!creds.length) throw new NotFound('Chave de acesso');
    const options = await generateAuthenticationOptions({
      rpID: this.rpId,
      allowCredentials: creds.map((c) => ({ id: c.credential_id, transports: c.transports })),
      userVerification: 'required',
      timeout: CHALLENGE_MINUTES * 60_000,
    });
    await this.storeChallenge(session.id, options.challenge, 'AUTHENTICATE');
    return options;
  }

  /** Verifies a login assertion and upgrades the pending session (rotated). */
  async login(session: SessionRow, response: z.infer<typeof WebAuthnAuthenticationResponse>, client: ClientInfo): Promise<IssuedSession> {
    await this.throttle.assertAllowed([`mfa:${session.user_id}`]);
    const user = await this.auth.userById(session.user_id);
    if (!user || user.status !== 'ACTIVE') throw new Unauthenticated();
    const challenge = await this.takeChallenge(session.id, 'AUTHENTICATE');
    const ok = await this.verifyAssertion(session.user_id, response, challenge);
    if (!ok) {
      await this.auth.recordMfaFailure(session, user, client, 'passkey');
      throw new Unauthenticated('Chave de acesso inválida');
    }
    return this.auth.completeMfa(session.id, user, client, 'passkey');
  }

  /** Step-up options for an ACTIVE session. */
  async stepUpOptions(actor: Actor) {
    const creds = await this.credentials(actor.userId);
    if (!creds.length) throw new NotFound('Chave de acesso');
    const options = await generateAuthenticationOptions({
      rpID: this.rpId,
      allowCredentials: creds.map((c) => ({ id: c.credential_id, transports: c.transports })),
      userVerification: 'required',
      timeout: CHALLENGE_MINUTES * 60_000,
    });
    await this.storeChallenge(actor.sessionId, options.challenge, 'STEP_UP');
    return options;
  }

  /** Verifies a step-up assertion and stamps the session. */
  async stepUp(actor: Actor, response: z.infer<typeof WebAuthnAuthenticationResponse>) {
    await this.throttle.assertAllowed([`mfa:${actor.userId}`]);
    const challenge = await this.takeChallenge(actor.sessionId, 'STEP_UP');
    if (!(await this.verifyAssertion(actor.userId, response, challenge))) {
      await this.throttle.recordFailure(`mfa:${actor.userId}`, 10);
      await this.audit.record({
        companyId: actor.companyId,
        actorUserId: actor.userId,
        action: 'auth.step_up',
        outcome: 'FAILURE',
        requestId: actor.requestId,
        clientIp: actor.clientIp,
        details: { method: 'passkey' },
      });
      throw new Unauthenticated('Chave de acesso inválida');
    }
    await this.auth.markStepUp(actor, 'passkey');
  }

  // ------------------------------------------------------------------ internals

  private async credentials(userId: string): Promise<CredentialRow[]> {
    return this.database.systemTx((tx) =>
      rows<CredentialRow>(
        tx,
        sql`SELECT id, user_id, credential_id, public_key, sign_count::text, transports, name
            FROM webauthn_credentials WHERE user_id = ${userId} AND revoked_at IS NULL`,
      ),
    );
  }

  /** Verifies an assertion against the user's OWN credential and advances its sign counter. */
  private async verifyAssertion(
    userId: string,
    response: z.infer<typeof WebAuthnAuthenticationResponse>,
    challenge: string,
  ): Promise<boolean> {
    const cred = (await this.credentials(userId)).find((c) => c.credential_id === response.id);
    if (!cred) return false; // credential of another user/tenant or revoked
    try {
      const v = await verifyAuthenticationResponse({
        response: response as never,
        expectedChallenge: challenge,
        expectedOrigin: this.cfg.WEB_ORIGIN,
        expectedRPID: this.rpId,
        requireUserVerification: true,
        credential: {
          id: cred.credential_id,
          publicKey: new Uint8Array(cred.public_key),
          counter: Number(cred.sign_count),
          transports: cred.transports,
        },
      });
      if (!v.verified) return false;
      await this.database.systemTx((tx) =>
        tx.execute(
          sql`UPDATE webauthn_credentials SET sign_count = ${v.authenticationInfo.newCounter}, last_used_at = now() WHERE id = ${cred.id}`,
        ),
      );
      return true;
    } catch {
      return false;
    }
  }

  private async storeChallenge(sessionId: string, challenge: string, purpose: Purpose): Promise<void> {
    await this.database.systemTx((tx) =>
      tx.execute(sql`UPDATE sessions SET webauthn_challenge = ${challenge}, webauthn_challenge_purpose = ${purpose},
          webauthn_challenge_expires_at = now() + make_interval(mins => ${CHALLENGE_MINUTES}) WHERE id = ${sessionId}`),
    );
  }

  /** Atomically reads AND clears the challenge (single use), checking purpose and expiry. */
  private async takeChallenge(sessionId: string, purpose: Purpose): Promise<string> {
    const r = await this.database.systemTx((tx) =>
      row<{ challenge: string | null; purpose: string | null; expires: Date | string | null }>(
        tx,
        sql`UPDATE sessions s SET webauthn_challenge = NULL, webauthn_challenge_purpose = NULL, webauthn_challenge_expires_at = NULL
            FROM (SELECT id, webauthn_challenge, webauthn_challenge_purpose, webauthn_challenge_expires_at FROM sessions WHERE id = ${sessionId} FOR UPDATE) old
            WHERE s.id = old.id
            RETURNING old.webauthn_challenge AS challenge, old.webauthn_challenge_purpose AS purpose, old.webauthn_challenge_expires_at AS expires`,
      ),
    );
    const expires = asDate(r?.expires);
    if (!r?.challenge || r.purpose !== purpose || !expires || expires.getTime() < Date.now()) {
      throw new Conflict('Pedido de chave de acesso expirado; tente novamente', 'PASSKEY_CHALLENGE_INVALID');
    }
    return r.challenge;
  }
}
